package com.jamshed.hrms.controller; import com.jamshed.hrms.entity.Department; import com.jamshed.hrms.repository.DepartmentRepository; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestController @RequestMapping("/api/departments") public class DepartmentController {private final DepartmentRepository r;public DepartmentController(DepartmentRepository r){this.r=r;}@GetMapping public List<Department> all(){return r.findAll();}@PostMapping public Department create(@RequestBody Department d){return r.save(d);}@PutMapping("/{id}") public Department update(@PathVariable Long id,@RequestBody Department next){Department d=r.findById(id).orElseThrow(()->new com.jamshed.hrms.exception.ResourceNotFoundException("Department not found"));d.setName(next.getName());d.setCode(next.getCode());d.setDescription(next.getDescription());d.setActive(next.isActive());return r.save(d);}}
